function uniqueBy(items, keyOf) {
  const seen = new Set();
  const result = [];
  for (const item of items) {
    const key = keyOf(item);
    if (!seen.has(key)) {
      seen.add(key);
      result.push(item);
    }
  }
  return result;
}

module.exports = { uniqueBy };

const test = require('node:test');
const assert = require('node:assert/strict');
const { uniqueBy } = require('../src/solution.cjs');

test('keeps first item per key in input order', () => {
  const items = [
    { id: 1, v: 'a' },
    { id: 2, v: 'b' },
    { id: 1, v: 'c' },
    { id: 3, v: 'd' },
    { id: 2, v: 'e' },
  ];
  assert.deepEqual(uniqueBy(items, (x) => x.id), [
    { id: 1, v: 'a' },
    { id: 2, v: 'b' },
    { id: 3, v: 'd' },
  ]);
});

test('does not mutate input and returns a new array', () => {
  const items = [1, 1, 2];
  const copy = [...items];
  const out = uniqueBy(items, (x) => x);
  assert.deepEqual(items, copy);
  assert.notEqual(out, items);
});

test('distinguishes number 1 from string "1"', () => {
  assert.deepEqual(uniqueBy([1, '1', 1, '1'], (x) => x), [1, '1']);
});

test('treats "__proto__" and similar as ordinary keys', () => {
  const items = ['__proto__', 'constructor', '__proto__', 'toString', 'constructor'];
  assert.deepEqual(uniqueBy(items, (x) => x), ['__proto__', 'constructor', 'toString']);
});

test('empty input returns []', () => {
  assert.deepEqual(uniqueBy([], (x) => x), []);
});

