import os
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from solution import parse_port


class ParsePortTests(unittest.TestCase):
    def test_boundaries(self):
        self.assertEqual(parse_port("1"), 1)
        self.assertEqual(parse_port("65535"), 65535)
        self.assertEqual(parse_port("80"), 80)

    def test_out_of_range(self):
        for s in ["0", "00", "65536", "99999", "100000000000000000000"]:
            with self.subTest(s=s), self.assertRaises(ValueError):
                parse_port(s)

    def test_leading_zeros(self):
        self.assertEqual(parse_port("0080"), 80)
        self.assertEqual(parse_port("000065535"), 65535)

    def test_spaces(self):
        self.assertEqual(parse_port("  443 "), 443)
        with self.assertRaises(ValueError):
            parse_port("4 43")

    def test_returns_int(self):
        self.assertIs(type(parse_port("8080")), int)

    def test_invalid_strings(self):
        bad = ["", " ", "   ", "+80", "-80", "80\n", "\t80", "80\r", "\n80",
               "8.0", "80.", ".80", "٣٠",  # Arabic-Indic digits
               "８０",  # fullwidth digits
               " 80",  # non-breaking space
               "0x50", "1e3", "8_0", "abc", "80a"]
        for s in bad:
            with self.subTest(s=s), self.assertRaises(ValueError):
                parse_port(s)

    def test_non_strings(self):
        for v in [None, 80, 80.0, b"80", True, ["80"]]:
            with self.subTest(v=v), self.assertRaises(ValueError):
                parse_port(v)


if __name__ == "__main__":
    unittest.main()

