def merge_intervals(intervals):
    """Merge closed integer intervals [start, end].

    Returns a new sorted list of non-overlapping [start, end] lists.
    Intervals that touch (e.g. [1,3] and [3,5]) are merged; the input
    list and its inner pairs are never modified.

    Time: O(n log n) for the sort; space: O(n) for the sorted copy and output.
    """
    merged = []
    for start, end in sorted(intervals, key=lambda p: (p[0], p[1])):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged
