        data = [[5, 6], [1, 3], [2, 4], [1, 3]]
        snapshot = copy.deepcopy(data)
        result = merge_intervals(data)
        self.assertEqual(data, snapshot)
        result[0][1] = 999
        self.assertEqual(data, snapshot)

    def test_tuples_input(self):
        self.assertEqual(merge_intervals([(1, 3), (2, 4)]), [[1, 4]])


if __name__ == "__main__":
    unittest.main()
