def merge_intervals(intervals):
    """Merge overlapping closed intervals.

    Intervals that share an endpoint, e.g. [1, 3] and [3, 5], are merged.
    Returns a new sorted list of new [start, end] lists; the input and its
    inner pairs are not modified.

    Time O(n log n), space O(n).
    """
    merged = []
    for start, end in sorted(intervals, key=lambda p: (p[0], p[1])):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged
