def merge_intervals(intervals):
    """Merge closed integer intervals.

    Intervals that share at least one point (e.g. [1,3] and [3,5]) are merged;
    [1,3] and [4,5] are not. Returns a new sorted list of non-overlapping
    [start, end] lists. The input list and its pairs are not modified.

    Time: O(n log n) for the sort; Space: O(n) for the output and sorted copy.
