const test = require('node:test');
const assert = require('node:assert');
const { TTLCache } = require('../src/solution.cjs');

function setup() {
  let t = 1000;
  const clock = { now: () => t, advance: (n) => { t += n; } };
  return { clock, cache: new TTLCache(clock.now) };
}

test('returns value before expiry', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 100);
  clock.advance(99);
  assert.strictEqual(cache.get('a'), 1);
});

test('expires exactly at the expiry instant and removes entry', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 100);
  clock.advance(100);
  assert.strictEqual(cache.get('a'), undefined);
  assert.strictEqual(cache._entries.has('a'), false);
});

test('stays expired if clock does not move back', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 10);
  clock.advance(50);
  assert.strictEqual(cache.get('a'), undefined);
  assert.strictEqual(cache.get('a'), undefined);
});

test('later set resets expiry', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 100);
  clock.advance(60);
  cache.set('a', 2, 100);
  clock.advance(60);
  assert.strictEqual(cache.get('a'), 2);
  clock.advance(40);
  assert.strictEqual(cache.get('a'), undefined);
});

test('later set can shorten expiry', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 100);
  cache.set('a', 2, 10);
  clock.advance(10);
  assert.strictEqual(cache.get('a'), undefined);
});

test('falsy values are stored and returned', () => {
  const { cache } = setup();
  for (const v of [false, 0, null, '', NaN]) {
    cache.set('k', v, 10);
    assert.ok(Object.is(cache.get('k'), v));
  }
});

test('ttl 0 expires immediately', () => {
  const { cache } = setup();
  cache.set('a', 1, 0);
  assert.strictEqual(cache.get('a'), undefined);
});

test('missing key returns undefined', () => {
  const { cache } = setup();
  assert.strictEqual(cache.get('nope'), undefined);
});

test('invalid ttl throws RangeError and leaves existing entry intact', () => {
  const { cache } = setup();
  cache.set('a', 1, 100);
  for (const bad of [-1, NaN, Infinity, -Infinity, undefined, null, '5', {}]) {
    assert.throws(() => cache.set('a', 2, bad), RangeError);
  }
  assert.strictEqual(cache.get('a'), 1);
});

test('keys are independent', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 10);
  cache.set('b', 2, 20);
  clock.advance(10);
  assert.strictEqual(cache.get('a'), undefined);
  assert.strictEqual(cache.get('b'), 2);
});
