'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { retry } = require('../src/solution.cjs');

function fakeSleep() {
  const calls = [];
  const sleep = async (ms) => { calls.push(ms); };
  return { sleep, calls };
}

function flaky(failures, makeError = (i) => new Error(`fail ${i}`)) {
  let n = 0;
  const fn = async () => {
    n++;
    if (n <= failures) throw makeError(n);
    return `ok ${n}`;
  };
