  const { sleep, calls } = fakeSleep();
  const op = flaky(0);
  assert.equal(await retry(op, { attempts: 3, delayMs: 10, sleep }), 'ok 1');
  assert.equal(op.count(), 1);
  assert.deepEqual(calls, []);
});

