  const { sleep, calls } = fakeSleep();
  const op = flaky(2);
  assert.equal(await retry(op, { attempts: 5, delayMs: 7, sleep }), 'ok 3');
  assert.equal(op.count(), 3);
  assert.deepEqual(calls, [7, 7]);
});

