def valid(nodes, edges, order):
    pos = {n: i for i, n in enumerate(order)}
    return (len(order) == len(nodes) == len(pos)
            and set(order) == set(nodes)
            and all(pos[a] < pos[b] for a, b in edges))


class TopoTest(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(topological_order([], []), [])

    def test_isolated(self):
        self.assertTrue(valid(["a", "b", "c"], [], topological_order(["a", "b", "c"], [])))

    def test_chain_and_diamond(self):
        nodes = ["d", "c", "b", "a"]
        edges = [("a", "b"), ("a", "c"), ("b", "d"), ("c", "d")]
        self.assertTrue(valid(nodes, edges, topological_order(nodes, edges)))

    def test_duplicate_edges(self):
        nodes = ["a", "b"]
        edges = [("a", "b")] * 3
        self.assertEqual(topological_order(nodes, edges), ["a", "b"])

    def test_self_loop(self):
        with self.assertRaises(ValueError):
            topological_order(["a"], [("a", "a")])

    def test_cycle(self):
        with self.assertRaises(ValueError):
            topological_order(["a", "b", "c"], [("a", "b"), ("b", "c"), ("c", "a")])

    def test_cycle_with_acyclic_part(self):
