import re

_AGE_RE = re.compile(r"[0-9]+")


def _parse_rows(text):
    """Strict RFC 4180 style parser. Yields rows as lists of strings.

    Accepts \\n, \\r\\n or \\r as record separators outside quotes. A quote
    may only appear as the first character of a field (opening a quoted
    field) or doubled inside one; a closing quote must be followed by a
    comma, a record separator or end of input.
    """
    i, n = 0, len(text)
    while i < n:
        row = []
        while True:
            if i < n and text[i] == '"':
                i += 1
                parts = []
                while True:
                    j = text.find('"', i)
                    if j < 0:
                        raise ValueError("unterminated quoted field")
                    parts.append(text[i:j])
                    if text.startswith('""', j):
                        parts.append('"')
                        i = j + 2
                    else:
                        i = j + 1
                        break
                row.append("".join(parts))
                if i < n and text[i] not in ",\r\n":
                    raise ValueError("unexpected character after closing quote")
            else:
                j = i
                while j < n and text[j] not in ',"\r\n':
                    j += 1
                if j < n and text[j] == '"':
                    raise ValueError("quote inside unquoted field")
                row.append(text[i:j])
                i = j
            if i < n and text[i] == ",":
                i += 1
                continue
            break
        yield row
        if i < n:
            if text.startswith("\r\n", i):
                i += 2
            else:
                i += 1


def read_people(text):
    """Parse CSV text with header name,age into a list of dicts.

    Raises ValueError on a bad header, bad quoting, wrong column count,
    or an age that is not ASCII digits within 0..130.
    """
    rows = _parse_rows(text)
    if next(rows, None) != ["name", "age"]:
        raise ValueError("header must be exactly name,age")
    people = []
    for row in rows:
        if len(row) != 2:
            raise ValueError("expected exactly 2 columns, got %d" % len(row))
        name, age_text = row
        if not _AGE_RE.fullmatch(age_text):
            raise ValueError("invalid age: %r" % age_text)
        age = int(age_text)
        if age > 130:
            raise ValueError("age out of range: %d" % age)
        people.append({"name": name, "age": age})
    return people
