'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(v) {
  if (v === null || typeof v !== 'object') return false;
  const proto = Object.getPrototypeOf(v);
  return proto === Object.prototype || proto === null;
}

// Validates and deep-copies a JSON-like value. Throws on unsafe own keys,
// cycles, and values that are not JSON-like (functions, symbols, class instances).
function cloneValue(value, stack) {
  if (value === null || typeof value !== 'object') {
    if (typeof value === 'function' || typeof value === 'symbol') {
      throw new TypeError('Unsupported value type: ' + typeof value);
    }
    return value;
  }
  const isArr = Array.isArray(value);
  if (!isArr && !isPlainObject(value)) {
    throw new TypeError('Unsupported non-plain object');
  }
  if (stack.has(value)) throw new TypeError('Circular structure');
  stack.add(value);
  let out;
  if (isArr) {
    out = new Array(value.length);
    for (const key of Object.getOwnPropertyNames(value)) {
