'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(v) {
  if (v === null || typeof v !== 'object') return false;
  const proto = Object.getPrototypeOf(v);
  return proto === Object.prototype || proto === null;
}

// Deep-copies a value, rejecting unsafe own keys at any depth (arrays included).
function deepCopy(value, ancestors = new Set()) {
  if (value === null || typeof value !== 'object') return value;
  if (ancestors.has(value)) throw new TypeError('Circular reference not supported');
  ancestors.add(value);
  let out;
  if (Array.isArray(value)) {
    out = value.map((item) => deepCopy(item, ancestors));
  } else if (isPlainObject(value)) {
    out = {};
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) throw new TypeError(`Unsafe key: ${key}`);
      out[key] = deepCopy(value[key], ancestors);
    }
  } else {
    throw new TypeError('Unsupported value type');
  }
  ancestors.delete(value);
  return out;
}

function merge(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return deepCopy(override);
  const out = {};
  for (const key of Object.keys(base)) out[key] = deepCopy(base[key]);
  for (const key of Object.keys(override)) {
    out[key] = Object.prototype.hasOwnProperty.call(base, key) &&
      isPlainObject(base[key]) && isPlainObject(override[key])
      ? merge(base[key], override[key])
      : deepCopy(override[key]);
  }
  return out;
}

function mergeConfig(base, override) {
  // Validate both inputs up front so nothing is returned for unsafe input.
  deepCopy(base);
  deepCopy(override);
  return merge(base, override);
}

module.exports = { mergeConfig };
