    // remove a listener that was re-added later.
    return () => {
      const current = this._events.get(event);
      if (current && current.get(fn) === reg) {
        current.delete(fn);
        if (current.size === 0) this._events.delete(event);
      }
    };
  }

  off(event, fn) {
    const regs = this._events.get(event);
    if (!regs) return;
    regs.delete(fn);
    if (regs.size === 0) this._events.delete(event);
  }

  emit(event, value) {
    const regs = this._events.get(event);
    if (!regs) return;
    for (const fn of Array.from(regs.keys())) fn(value);
  }
}

module.exports = { Emitter };
