class Emitter {
  constructor() {
    // event -> Set of listeners (insertion order = registration order)
    this._events = new Map();
  }

  on(event, fn) {
    let set = this._events.get(event);
    if (!set) {
      set = new Set();
      this._events.set(event, set);
    }
    const added = !set.has(fn);
    if (added) set.add(fn);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      // A duplicate registration did not add anything, so it removes nothing.
      if (added) this.off(event, fn);
    };
  }

  off(event, fn) {
    const set = this._events.get(event);
    if (!set) return;
    set.delete(fn);
    if (set.size === 0) this._events.delete(event);
  }

  emit(event, value) {
    const set = this._events.get(event);
    if (!set) return;
    for (const fn of [...set]) fn(value);
  }
}

module.exports = { Emitter };
EOF
