import { test } from "node:test";
import assert from "node:assert/strict";
import { mapResult, unwrapOr } from "../src/solution.ts";
import type { Result } from "../src/solution.ts";

test("mapResult applies fn on success and can change the type", () => {
  const r: Result<number> = { ok: true, value: 2 };
  const mapped: Result<string> = mapResult(r, (n) => `n=${n}`);
  assert.deepEqual(mapped, { ok: true, value: "n=2" });
});

test("mapResult does not call fn on failure and keeps the error", () => {
  let calls = 0;
  const r: Result<number> = { ok: false, error: "boom" };
  const mapped: Result<string> = mapResult(r, (n) => {
    calls++;
    return String(n);
  });
  assert.equal(calls, 0);
  assert.deepEqual(mapped, { ok: false, error: "boom" });
});

test("mapResult lets fn exceptions propagate", () => {
  const r: Result<number> = { ok: true, value: 1 };
  assert.throws(
    () =>
      mapResult(r, () => {
        throw new Error("bad fn");
      }),
    /bad fn/,
  );
});

test("unwrapOr returns value on success and fallback on failure", () => {
  assert.equal(unwrapOr<number>({ ok: true, value: 5 }, 0), 5);
  assert.equal(unwrapOr<number>({ ok: false, error: "x" }, 0), 0);
});

test("narrowing works on the discriminant", () => {
  const r = mapResult<number, number>({ ok: true, value: 3 }, (n) => n * 2);
  if (r.ok) {
    const v: number = r.value;
    assert.equal(v, 6);
  } else {
    const e: string = r.error;
    assert.fail(e);
  }
});
