function lowerBound(numbers, target) {
  let lo = 0;
  let hi = numbers.length;
  while (lo < hi) {
    const mid = lo + ((hi - lo) >> 1);
    if (numbers[mid] < target) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

module.exports = { lowerBound };
EOF
