import os
import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))
from solution import resolve_upload


class ResolveUploadTests(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        base = Path(self._tmp.name).resolve()
        self.root = base / "root"
        self.sibling = base / "root_sibling"  # shares root's string prefix
        self.root.mkdir()
        self.sibling.mkdir()
        (self.root / "sub").mkdir()

    def test_nested_nonexistent(self):
        got = resolve_upload(self.root, "a/b/new.txt")
        self.assertEqual(got, self.root / "a" / "b" / "new.txt")
        self.assertFalse((self.root / "a").exists())

    def test_existing_file(self):
        (self.root / "sub" / "f.txt").write_text("x")
        self.assertEqual(resolve_upload(self.root, "sub/f.txt"),
                         self.root / "sub" / "f.txt")

    def test_inner_dotdot_ok(self):
        self.assertEqual(resolve_upload(self.root, "sub/../x.txt"),
                         self.root / "x.txt")

    def test_rejects_absolute(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, str(self.root / "x.txt"))

    def test_rejects_root_itself(self):
        for s in (".", "sub/..", "./"):
            with self.assertRaises(ValueError, msg=s):
                resolve_upload(self.root, s)

    def test_rejects_traversal(self):
        for s in ("../x", "sub/../../x", "../root_sibling/x"):
            with self.assertRaises(ValueError, msg=s):
                resolve_upload(self.root, s)

    def test_rejects_sibling_prefix(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "../root_sibling")

    def test_rejects_empty_and_nul(self):
        for s in ("", "a\0b"):
            with self.assertRaises(ValueError):
                resolve_upload(self.root, s)

    @unittest.skipUnless(hasattr(os, "symlink"), "needs symlinks")
    def test_symlink_dir_outside_rejected(self):
        os.symlink(self.sibling, self.root / "link")
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "link/new.txt")
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "link")

    @unittest.skipUnless(hasattr(os, "symlink"), "needs symlinks")
    def test_symlink_file_outside_rejected(self):
        (self.sibling / "secret").write_text("s")
        os.symlink(self.sibling / "secret", self.root / "l")
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "l")

    @unittest.skipUnless(hasattr(os, "symlink"), "needs symlinks")
    def test_symlink_inside_allowed(self):
        os.symlink(self.root / "sub", self.root / "alias")
        self.assertEqual(resolve_upload(self.root, "alias/n.txt"),
                         self.root / "sub" / "n.txt")


if __name__ == "__main__":
    unittest.main()
